#nullable enable // autogenerated

using PVZEngine;
using PVZEngine.Damages;
using PVZEngine.Entities;
using PVZEngine.Definitions;
using MVZ2.GameContent.Entities;

namespace MVZ2.GameContent.Enemies
{
    [AutoEntityBehaviourDefinition(VanillaEnemyNames.RandomMannequin)]
    public class RandomMannequin : AIEntityBehaviour
    {
        public RandomMannequin(string nsp, string name) : base(nsp, name)
        {
        }
        public override void PostDeath(Entity entity, DeathInfo info)
        {
            base.PostDeath(entity, info);
            // 死亡后召唤人偶种族（Mannequin_Exp，使用 <Mannequin_Exp> 模板）的敌人
            HealthLossSpawnHelper.SpawnOnDeath(entity, info, SpawnWhitelist, SpawnWeights);
        }

        #region 可生成敌人加权池

        // 人偶种族（mvz2:Mannequin_Exp）敌人列表，不含随机系列
        private static NamespaceID[] SpawnWhitelist = new NamespaceID[]
        {
            VanillaEnemyID.Mannequin,
            VanillaEnemyID.ImpMannequin,
            VanillaEnemyID.MegaImpMannequin,
            VanillaEnemyID.ImpHerobrineMannequin,
            VanillaEnemyID.CannoneerMannequin,
            VanillaEnemyID.WickedHermitMannequin,
            VanillaEnemyID.MutantMannequin,
        };

        // 对应每种敌人的生成权重，数值越大越容易被抽中（默认 1，待细调）
        private static int[] SpawnWeights = new int[]
        {
            1, 1, 1, 1, 1, 1, 1,
        };

        #endregion
    }
}
